package io.github.mekkiamiri.ratchet.order.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.List;
import org.junit.jupiter.api.Test;

class NotificationServiceTest {

    @Test
    void keepsTheSentMessages() {
        NotificationService notifications = mock(NotificationService.class);
        when(notifications.sentMessages()).thenReturn(List.of("Commande 1 validée pour ada"));

        assertThat(notifications.sentMessages()).hasSize(1);
    }
}
